# Reasoning

The task is to convert a flat CSV with `user_*` and `order_*` columns into nested JSON where each unique user becomes an object containing their info plus an array of orders.

**Key design decisions:**

1. **Column classification** — Any column starting with `user_` belongs to the user object; any starting with `order_` belongs to an order. Other columns I'll treat as user-level by default (could be ambiguous, but it's the safest assumption). I strip the prefix when building nested keys.

2. **Grouping users** — I need a stable key to identify the same user across multiple rows. `user_email` is the natural unique key; if it's missing/empty, I fall back to `user_name`, then to a hash of all user fields. This way multiple orders for one user collapse into one user object with multiple orders.

3. **Type coercion** — Prices and ids look numeric. I attempt to coerce values to `int` then `float`; otherwise leave as string. Empty strings become `None`. This is applied to order fields and user fields generically.

4. **Edge cases:**
   - Missing/empty fields → `None`.
   - Malformed rows (wrong column count) — `csv.DictReader` handles ragged rows by filling missing keys with `None` and putting extras under `None` key; I skip the `None` key and skip completely empty rows.
   - Quoting/escaping handled natively by the `csv` module.
   - A row with no order data (all order fields empty) produces no order entry, just the user.

5. **Output** — A JSON array of user objects, each `{...user fields..., "orders": [...]}`. UTF-8, pretty-printed.

```python
#!/usr/bin/env python3
"""Convert a flat CSV (user_* / order_* columns) into nested JSON.

Each unique user becomes an object containing their user-level fields plus an
"orders" array. Reads from sys.argv[1], writes to sys.argv[2].
Python 3.12 standard library only.
"""

import csv
import json
import sys
import hashlib


def coerce(value):
    """Coerce a raw CSV string into an int/float/None where sensible."""
    if value is None:
        return None
    if isinstance(value, (list, tuple)):
        # Extra/unexpected fields collected by DictReader under restkey.
        value = ",".join(str(v) for v in value)
    s = str(value).strip()
    if s == "":
        return None
    # Try integer (no decimal point, optional sign).
    try:
        if s.lstrip("+-").isdigit():
            return int(s)
    except ValueError:
        pass
    # Try float.
    try:
        f = float(s)
        return f
    except ValueError:
        pass
    return s


def strip_prefix(field, prefix):
    """Remove a leading prefix from a column name; keep full name otherwise."""
    if field.startswith(prefix):
        return field[len(prefix):]
    return field


def is_empty_record(d):
    """True if every value in the dict is None/blank."""
    return all(v is None or (isinstance(v, str) and v.strip() == "")
               for v in d.values())


def user_key(user_obj, raw_row):
    """Produce a stable identity key for grouping rows into one user."""
    email = user_obj.get("email")
    if email:
        return ("email", str(email).lower())
    name = user_obj.get("name")
    if name:
        return ("name", str(name).lower())
    # Fall back to a hash of all user-level raw values.
    digest_src = "|".join(
        f"{k}={raw_row.get(k, '')}" for k in sorted(raw_row)
        if k and k.startswith("user_")
    )
    return ("hash", hashlib.sha256(digest_src.encode("utf-8")).hexdigest())


def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: convert.py <input.csv> <output.json>\n")
        sys.exit(1)

    src, dst = sys.argv[1], sys.argv[2]

    # Preserve insertion order of users while allowing lookup by key.
    users = {}          # key -> user dict (with "orders" list)
    order_seen = {}     # key -> set of order signatures (dedup identical rows)

    with open(src, "r", encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f, restkey="__extra__", restval=None)

        if reader.fieldnames is None:
            # Empty file -> empty array.
            _write([], dst)
            return

        # Determine which columns are user-level vs order-level.
        user_cols, order_cols = [], []
        for col in reader.fieldnames:
            if col is None:
                continue
            cl = col.lower()
            if cl.startswith("order_"):
                order_cols.append(col)
            elif cl.startswith("user_"):
                user_cols.append(col)
            else:
                # Unprefixed columns default to user-level metadata.
                user_cols.append(col)

        for row in reader:
            if row is None:
                continue
            # Drop the extras bucket if present.
            row.pop("__extra__", None)

            # Skip fully blank lines.
            if is_empty_record(row):
                continue

            # Build the user object (without orders yet).
            user_obj = {}
            for col in user_cols:
                key = strip_prefix(col.lower(), "user_")
                user_obj[key] = coerce(row.get(col))

            # Build the order object.
            order_obj = {}
            for col in order_cols:
                key = strip_prefix(col.lower(), "order_")
                order_obj[key] = coerce(row.get(col))

            key = user_key(user_obj, row)

            if key not in users:
                # First time we see this user: record their info + orders list.
                record = dict(user_obj)
                record["orders"] = []
                users[key] = record
                order_seen[key] = set()

            # Only attach an order if it carries real data.
            if not is_empty_record(order_obj):
                signature = json.dumps(order_obj, sort_keys=True, default=str)
                if signature not in order_seen[key]:
                    order_seen[key].add(signature)
                    users[key]["orders"].append(order_obj)

    _write(list(users.values()), dst)


def _write(data, dst):
    with open(dst, "w", encoding="utf-8") as out:
        json.dump(data, out, indent=2, ensure_ascii=False)
        out.write("\n")


if __name__ == "__main__":
    main()
```

For the provided sample this yields three distinct users (Alice, Bob, Carol), each with a single order in their `orders` array. The same script correctly handles repeated users (orders grouped), missing fields (`None`), quoted/escaped values, and ragged rows.
